import fs from "node:fs";
import path from "node:path";

import { SAMPLES, expect, test, type APIRequestContext } from "../../fixtures";

type DocumentKind = "w9" | "insurance_certificate" | "contract";

const KIND_PATTERNS: Record<DocumentKind, RegExp> = {
  w9: /w-?9/i,
  insurance_certificate: /insur|coi|certificate/i,
  contract: /contract|msa|agreement/i,
};

function minimalPdf(text: string): Buffer {
  return Buffer.from(
    `%PDF-1.4
1 0 obj << /Type /Catalog /Pages 2 0 R >> endobj
2 0 obj << /Type /Pages /Kids [3 0 R] /Count 1 >> endobj
3 0 obj << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R >> endobj
4 0 obj << /Length ${text.length + 30} >> stream
BT /F1 12 Tf 72 720 Td (${text}) Tj ET
endstream endobj
trailer << /Root 1 0 R >>
%%EOF
`,
  );
}

function documentFile(kind: DocumentKind): { name: string; mimeType: string; buffer: Buffer } {
  let files: string[] = [];
  try {
    files = fs.readdirSync(SAMPLES).filter((f) => fs.statSync(path.join(SAMPLES, f)).isFile());
  } catch {
    files = [];
  }
  const match = files.find((f) => KIND_PATTERNS[kind].test(f));
  if (match) {
    const ext = path.extname(match).toLowerCase();
    const mimeType =
      ext === ".pdf"
        ? "application/pdf"
        : ext === ".png"
          ? "image/png"
          : ext === ".jpg" || ext === ".jpeg"
            ? "image/jpeg"
            : "application/octet-stream";
    return { name: match, mimeType, buffer: fs.readFileSync(path.join(SAMPLES, match)) };
  }
  return { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: minimalPdf(`${kind} document`) };
}

async function createVendor(member: APIRequestContext, name: string, i: number): Promise<string> {
  const response = await member.post("/api/vendors", {
    data: { name, category: "logistics", contact_email: `ops+ven05-${i}@example.com` },
  });
  expect(response.status(), `create vendor ${name}`).toBe(201);
  return (await response.json()).id as string;
}

async function approveVendor(
  member: APIRequestContext,
  reviewer: APIRequestContext,
  vendorId: string,
): Promise<void> {
  const kinds: DocumentKind[] = ["w9", "insurance_certificate", "contract"];
  for (const kind of kinds) {
    const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: { kind, file: documentFile(kind) },
    });
    expect(upload.status(), `upload ${kind}`).toBe(201);
    const docId = (await upload.json()).id as string;
    await expect
      .poll(
        async () => (await (await member.get(`/api/documents/${docId}`)).json()).status,
        { timeout: 60_000 },
      )
      .not.toBe("processing");
    const doc = await (await member.get(`/api/documents/${docId}`)).json();
    expect(doc.status, `document ${kind} extracted`).toBe("extracted");
  }

  const submit = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submit.status(), "submit vendor").toBe(200);
  expect((await submit.json()).status).toBe("in_review");

  const queueResponse = await reviewer.get("/api/review-queue");
  expect(queueResponse.status()).toBe(200);
  const queue = (await queueResponse.json()) as Array<{
    vendor_id: string;
    extractions: Array<{ id: string; status: string }>;
  }>;
  const item = queue.find((q) => q.vendor_id === vendorId);
  expect(item, "vendor appears in review queue").toBeTruthy();
  for (const extraction of item!.extractions.filter((e) => e.status === "pending_review")) {
    const decision = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    expect(decision.status(), "approve extraction").toBe(200);
  }

  await expect
    .poll(async () => (await (await member.get(`/api/vendors/${vendorId}`)).json()).status, {
      timeout: 30_000,
    })
    .toBe("approved");
}

test(
  "list vendors with search, status filter, and pagination",
  { tag: "@VEN-05" },
  async ({ apiAs }) => {
    test.setTimeout(300_000);

    // Arrange: a uniquely-tagged set of 25 vendors, 5 of which are approved.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const token = `ven05${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;

    const names = Array.from({ length: 25 }, (_, i) =>
      i < 3 ? `${token} FrEiGhT Lines ${i}` : `${token} Vendor ${i}`,
    );
    const ids: string[] = [];
    for (let i = 0; i < names.length; i++) {
      ids.push(await createVendor(member, names[i], i));
    }
    await Promise.all(ids.slice(0, 5).map((id) => approveVendor(member, reviewer, id)));

    // Act + Assert: status filter
    const approvedResponse = await member.get("/api/vendors", {
      params: { q: token, status: "approved" },
    });
    expect(approvedResponse.status()).toBe(200);
    const approved = await approvedResponse.json();
    expect(approved.items).toHaveLength(5);
    expect(approved.total).toBe(5);
    for (const vendor of approved.items) {
      expect(vendor.status).toBe("approved");
      expect(ids.slice(0, 5)).toContain(vendor.id);
    }

    // Act + Assert: pagination
    const pageResponse = await member.get("/api/vendors", {
      params: { q: token, limit: 10, offset: 20 },
    });
    expect(pageResponse.status()).toBe(200);
    const page = await pageResponse.json();
    expect(page.items).toHaveLength(5);
    expect(page.total).toBe(25);
    expect(page.limit).toBe(10);
    expect(page.offset).toBe(20);
    for (const vendor of page.items) {
      expect(ids).toContain(vendor.id);
    }

    // Act + Assert: search is case-insensitive on name
    const searchResponse = await member.get("/api/vendors", {
      params: { q: "freight", limit: 100 },
    });
    expect(searchResponse.status()).toBe(200);
    const search = await searchResponse.json();
    expect(search.items.length).toBeGreaterThan(0);
    for (const vendor of search.items) {
      expect(vendor.name.toLowerCase()).toContain("freight");
    }

    // Our mixed-case freight vendors are found by the lowercase search
    const scopedSearch = await member.get("/api/vendors", {
      params: { q: `${token} freight`, limit: 100 },
    });
    expect(scopedSearch.status()).toBe(200);
    const scoped = await scopedSearch.json();
    expect(scoped.total).toBe(3);
    for (const vendor of scoped.items) {
      expect(vendor.name.toLowerCase()).toContain("freight");
    }
  },
);
